package pl.zagranietyper.service;
import org.junit.jupiter.api.Test;import pl.zagranietyper.provider.FootballPeriodStatisticsProvider;import java.time.Instant;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class FootballSecondaryFixtureMatcherTest {@Test void requiresUniqueExactTeamsTimeScore(){var m=new FootballSecondaryFixtureMatcher();var f=new FootballSecondaryFixtureMatcher.Fixture(1,Instant.parse("2024-10-13T16:00:00Z"),"Finland","England",1,3);var e=new FootballPeriodStatisticsProvider.Event("x",Instant.parse("2024-10-13T16:00:00Z"),"Finland","England",1,3,true);assertTrue(m.match(f,List.of(e)).mapped());assertEquals(FootballSecondaryFixtureMatcher.Status.AMBIGUOUS,m.match(f,List.of(e,e)).status());assertEquals(FootballSecondaryFixtureMatcher.Status.UNRESOLVED,m.match(f,List.of(new FootballPeriodStatisticsProvider.Event("y",e.kickoff(),"Finland U21","England",1,3,true))).status());}}
